Type: C<Message> (L<Google::Cloud::Discoveryengine::V1alpha::SearchService::SearchRequest::DataStoreSpec>)

Specs defining dataStores to filter on in a search call and configurations
for those dataStores. This is only considered for engines with multiple
dataStores use case. For single dataStore within an engine, they should
use the specs at the top level.

=item * C<< $msg->filter() >> / C<< $msg->filter($value) >>

Type: C<String>

The filter syntax consists of an expression language for constructing a
predicate from one or more fields of the documents being filtered. Filter
expression is case-sensitive.

If this field is unrecognizable, an  `INVALID_ARGUMENT`  is returned.

Filtering in Vertex AI Search is done by mapping the LHS filter key to a
key property defined in the Vertex AI Search backend -- this mapping is
defined by the customer in their schema. For example a media customer might
have a field 'name' in their schema. In this case the filter would look
like this: filter --> name:'ANY("king kong")'

For more information about filtering including syntax and filter
operators, see
[Filter](https://cloud.google.com/generative-ai-app-builder/docs/filter-search-metadata)

=item * C<< $msg->canonical_filter() >> / C<< $msg->canonical_filter($value) >>

Type: C<String>

The default filter that is applied when a user performs a search without
checking any filters on the search page.

The filter applied to every search request when quality improvement such as
query expansion is needed. In the case a query does not have a sufficient
amount of results this filter will be used to determine whether or not to
enable the query expansion flow. The original filter will still be used for
the query expanded search.
This field is strongly recommended to achieve high search quality.

For more information about filter syntax, see
[SearchRequest.filter][google.cloud.discoveryengine.v1alpha.SearchRequest.filter].

=item * C<< $msg->order_by() >> / C<< $msg->order_by($value) >>

