=item * C<< $msg->custom_fine_tuning_spec() >> / C<< $msg->custom_fine_tuning_spec($value) >>

Type: C<Message> (L<Google::Cloud::Discoveryengine::V1alpha::Common::CustomFineTuningSpec>)

